@ResourceLock(Resources.SYSTEM_PROPERTIES)
class NativeLazyResultReplayTest {
	@Test
	void independentReadersCrossSpillAndResumeAfterEarlyCloseWithoutReevaluating() {
		String old = System.getProperty(NativeCountGroupStore.MAX_BYTES_PROPERTY);
		System.setProperty(NativeCountGroupStore.MAX_BYTES_PROPERTY, "16384");
		long files = NativeLazyResultReplay.OPEN_FILES.get(), spills = NativeLazyResultReplay.SPILLS.get();
		NativeExecutionContext context = new NativeExecutionContext();
		var ledger = context.memoryLedger();
		Producer producer = new Producer(context, 64);
		try {
			NativeLazyResultReplay replay = context.nativeState(new Object(), () -> replay(context, producer));
			assertThat(producer.position).isEqualTo(1);
			try (NativeResultCursor first = replay.cursor(context.cancellation());
					NativeResultCursor second = replay.cursor(context.cancellation())) {
				for (int index = 0; index < 32; index++) {
					check(first.next(), index);
				}
				for (int index = 0; index < 16; index++) {
					check(second.next(), index);
				}
				assertThat(NativeLazyResultReplay.SPILLS.get()).isGreaterThan(spills);
				first.close();
				for (int index = 16; index < 64; index++) {
					check(second.next(), index);
				}
				assertThat(second.next()).isNull();
			}
			try (NativeResultCursor replayed = replay.cursor(context.cancellation())) {
				for (int index = 0; index < 64; index++) {
					check(replayed.next(), index);
				}
				assertThat(replayed.next()).isNull();
			}
			assertThat(producer.position).isEqualTo(64);
			assertThat(producer.closes).hasValue(1);
			assertThat(ledger.usedBytes()).isPositive();
		} finally {
			context.close();
			restore(old);
		}
		assertThat(context.isClosed()).isTrue();
		assertThat(ledger.usedBytes()).isZero();
		assertThat(NativeLazyResultReplay.OPEN_FILES.get()).isEqualTo(files);
	}

	@Test
	void failureAfterSpillIsTerminalForEveryReaderAndFutureOpen() {
		String old = System.getProperty(NativeCountGroupStore.MAX_BYTES_PROPERTY);
		System.setProperty(NativeCountGroupStore.MAX_BYTES_PROPERTY, "16384");
		long files = NativeLazyResultReplay.OPEN_FILES.get();
		NativeExecutionContext context = new NativeExecutionContext();
		var ledger = context.memoryLedger();
		Producer producer = new Producer(context, 64);
		producer.failAt = 32;
		try {
			NativeLazyResultReplay replay = context.nativeState(new Object(), () -> replay(context, producer));
			try (NativeResultCursor first = replay.cursor(context.cancellation());
					NativeResultCursor second = replay.cursor(context.cancellation())) {
				for (int index = 0; index < 32; index++) {
					check(first.next(), index);
				}
				check(second.next(), 0);
				assertThat(NativeLazyResultReplay.OPEN_FILES.get()).isEqualTo(files + 1L);
				assertThatThrownBy(first::next).isSameAs(producer.failure);
				assertThatThrownBy(second::next).isSameAs(producer.failure);
			}
			assertThatThrownBy(() -> replay.cursor(context.cancellation())).isSameAs(producer.failure);
			assertThat(producer.closes).hasValue(1);
		} finally {
			context.close();
			restore(old);
		}
		assertThat(ledger.usedBytes()).isZero();
		assertThat(NativeLazyResultReplay.OPEN_FILES.get()).isEqualTo(files);
	}

	@Test
	void initialProducerAdvanceRetainsOwnerUntilInitializationDrains() throws Exception {
		NativeExecutionContext context = new NativeExecutionContext();
		var ledger = context.memoryLedger();
		Producer producer = new Producer(context, 4);
		producer.entered = new CountDownLatch(1);
		producer.release = new CountDownLatch(1);
		producer.blockAt = 0;
		var executor = Executors.newSingleThreadExecutor();
		try {
			var initializing = executor
					.submit(() -> context.nativeState(new Object(), () -> replay(context, producer)));
			assertThat(producer.entered.await(10, TimeUnit.SECONDS)).isTrue();
			context.close();
			assertThat(context.isClosed()).as("active first-row initialization still owns native source access")
					.isFalse();
			assertThat(producer.closes).hasValue(0);
			assertThat(ledger.usedBytes()).isPositive();
			producer.release.countDown();
			assertThatThrownBy(() -> initializing.get(10, TimeUnit.SECONDS)).isInstanceOf(ExecutionException.class)
					.hasCauseInstanceOf(IllegalStateException.class);
			assertThat(context.isClosed()).isTrue();
			assertThat(producer.closes).hasValue(1);
			assertThat(ledger.usedBytes()).isZero();
		} finally {
			producer.release.countDown();
			executor.shutdownNow();
			assertThat(executor.awaitTermination(10, TimeUnit.SECONDS)).isTrue();
			context.close();
		}
	}

	@Test
	void cancellationSignalsWithoutProducerLockAndDrainsBeforeOwnerCleanup() throws Exception {
		NativeExecutionContext context = new NativeExecutionContext();
		var ledger = context.memoryLedger();
		Producer producer = new Producer(context, 4);
		producer.entered = new CountDownLatch(1);
		producer.release = new CountDownLatch(1);
		var executor = Executors.newSingleThreadExecutor();
		try {
			NativeLazyResultReplay replay = context.nativeState(new Object(), () -> replay(context, producer));
			try (NativeResultCursor first = replay.cursor(context.cancellation());
					NativeResultCursor second = replay.cursor(context.cancellation())) {
				check(first.next(), 0);
				var active = executor.submit(first::next);
				assertThat(producer.entered.await(10, TimeUnit.SECONDS)).isTrue();
				context.close();
				assertThat(context.isClosed()).isFalse();
				assertThat(second.requestCancellation()).isTrue();
				assertThat(producer.cancellation.isCancellationRequested()).isTrue();
				assertThat(producer.closes).hasValue(0);
				assertThat(ledger.usedBytes()).isPositive();
				producer.release.countDown();
				assertThatThrownBy(() -> active.get(10, TimeUnit.SECONDS)).isInstanceOf(ExecutionException.class)
						.hasCauseInstanceOf(KernelQueryCancelledException.class);
				assertThatThrownBy(second::next).isInstanceOf(KernelQueryCancelledException.class);
			}
			assertThat(context.isClosed()).isTrue();
			assertThat(producer.closes).hasValue(1);
			assertThat(ledger.usedBytes()).isZero();
		} finally {
			producer.release.countDown();
			executor.shutdownNow();
			assertThat(executor.awaitTermination(10, TimeUnit.SECONDS)).isTrue();
			context.close();
		}
	}

	private static NativeLazyResultReplay replay(NativeExecutionContext context, Producer producer) {
		return new NativeLazyResultReplay(new String[] { "term", "length", "error" }, context,
				context.cancellation(), producer);
	}

	private static void check(NativeResultRow row, int index) {
		assertThat(row).isNotNull();
		assertThat(row.cell("term").value()).isEqualTo(SimpleValueFactory.getInstance().createLiteral(label(index)));
		assertThat(row.cell("length").codePointLength()).isEqualTo(index);
		assertThat(row.cell("error").state()).isEqualTo(NativeResultCell.State.ERROR);
	}

	private static String label(int index) {
		return index + "😀λ".repeat(256);
	}

	private static void restore(String old) {
		if (old == null) {
			System.clearProperty(NativeCountGroupStore.MAX_BYTES_PROPERTY);
		} else {
			System.setProperty(NativeCountGroupStore.MAX_BYTES_PROPERTY, old);
		}
	}

	private static final class Producer implements NativeResultCursor {
		private final NativeExecutionContext context;
		private final NativeCancellationToken cancellation;
		private final int limit;
		private final AtomicInteger closes = new AtomicInteger();
		private final IllegalStateException failure = new IllegalStateException("controlled spilled producer failure");
		private CountDownLatch entered, release;
		private int position, failAt = -1, blockAt = 1;
		private boolean closed;

		private Producer(NativeExecutionContext context, int limit) {
			this.context = context;
			this.cancellation = new NativeCancellationToken(context.cancellation());
			this.limit = limit;
		}

		@Override
		public NativeResultRow next() {
			if (position == failAt) {
				throw failure;
			}
			if (position == limit) {
				return null;
			}
			if (position == blockAt && entered != null) {
				entered.countDown();
				try {
					assertThat(release.await(10, TimeUnit.SECONDS)).isTrue();
				} catch (InterruptedException failure) {
					Thread.currentThread().interrupt();
					throw new AssertionError(failure);
				}
			}
			int index = position++;
			return new NativeResultRow(new String[] { "term", "length", "error" }, new NativeResultCell[] {
					NativeResultCell.term(SimpleValueFactory.getInstance().createLiteral(label(index))),
					NativeResultCell.lexicalLength(index), NativeResultCell.error() });
		}

		@Override
		public NativeCancellationToken cancellation() {
			return cancellation;
		}

		@Override
		public NativeExecutionContext executionContext() {
			return context;
		}

		@Override
		public void close() {
			if (!closed) {
				closed = true;
				closes.incrementAndGet();
			}
		}
	}
}
